module idelay_sweep(input clk, input c0, input c1, input c2, input c3, output reg r, input p0, input p1, input p2, input p3, input p4, input p5, input p6, input p7, input p8, input p9, input p10, input p11, input p12, input p13, input p14, input p15, input p16, input p17, input p18, input p19, input p20, input p21, input p22, input p23, input p24, input p25, input p26, input p27, input p28);
  wire gclk; BUFG bg(.I(clk), .O(gclk));
  wire d0;
  IDELAYE2 u0(.IDATAIN(p0), .DATAOUT(d0));
  wire d1;
  IDELAYE2 #(.IDELAY_VALUE(1)) u1(.IDATAIN(p1), .DATAOUT(d1));
  wire d2;
  IDELAYE2 #(.IDELAY_VALUE(2)) u2(.IDATAIN(p2), .DATAOUT(d2));
  wire d3;
  IDELAYE2 #(.IDELAY_VALUE(4)) u3(.IDATAIN(p3), .DATAOUT(d3));
  wire d4;
  IDELAYE2 #(.IDELAY_VALUE(8)) u4(.IDATAIN(p4), .DATAOUT(d4));
  wire d5;
  IDELAYE2 #(.IDELAY_VALUE(16)) u5(.IDATAIN(p5), .DATAOUT(d5));
  wire d6;
  IDELAYE2 #(.IDELAY_VALUE(31)) u6(.IDATAIN(p6), .DATAOUT(d6));
  wire d7;
  IDELAYE2 #(.HIGH_PERFORMANCE_MODE("TRUE")) u7(.IDATAIN(p7), .DATAOUT(d7));
  wire d8;
  IDELAYE2 #(.SIGNAL_PATTERN("CLOCK")) u8(.IDATAIN(p8), .DATAOUT(d8));
  wire d9;
  IDELAYE2 #(.IS_IDATAIN_INVERTED(1'b1)) u9(.IDATAIN(p9), .DATAOUT(d9));
  wire d10;
  IDELAYE2 #(.CINVCTRL_SEL("TRUE")) u10(.IDATAIN(p10), .DATAOUT(d10), .CINVCTRL(c1));
  wire d11;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE")) u11(.IDATAIN(p11), .DATAOUT(d11), .C(gclk), .CE(c0), .INC(c1));
  wire d12;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE"),.IDELAY_VALUE(5)) u12(.IDATAIN(p12), .DATAOUT(d12), .C(gclk), .CE(c0), .INC(c1));
  wire d13;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE"),.IS_C_INVERTED(1'b1)) u13(.IDATAIN(p13), .DATAOUT(d13), .C(gclk), .CE(c0), .INC(c1));
  wire d14;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE"),.CINVCTRL_SEL("TRUE")) u14(.IDATAIN(p14), .DATAOUT(d14), .C(gclk), .CE(c0), .INC(c1), .CINVCTRL(c2));
  wire d15;
  IDELAYE2 #(.IDELAY_TYPE("VAR_LOAD")) u15(.IDATAIN(p15), .DATAOUT(d15), .C(gclk), .CE(c0), .INC(c1), .LD(c2), .CNTVALUEIN({c3, c2, c1, c0, c3}));
  wire d16;
  IDELAYE2 #(.IDELAY_TYPE("VAR_LOAD"),.IDELAY_VALUE(9)) u16(.IDATAIN(p16), .DATAOUT(d16), .C(gclk), .CE(c0), .INC(c1), .LD(c2), .CNTVALUEIN({c3, c2, c1, c0, c3}));
  wire d17;
  IDELAYE2 #(.IDELAY_TYPE("VAR_LOAD_PIPE")) u17(.IDATAIN(p17), .DATAOUT(d17), .C(gclk), .CE(c0), .INC(c1), .LD(c2), .CNTVALUEIN({c3, c2, c1, c0, c3}), .LDPIPEEN(c3), .REGRST(c0));
  wire d18;
  IDELAYE2 #(.IDELAY_TYPE("VAR_LOAD_PIPE"),.PIPE_SEL("TRUE")) u18(.IDATAIN(p18), .DATAOUT(d18), .C(gclk), .CE(c0), .INC(c1), .LD(c2), .CNTVALUEIN({c3, c2, c1, c0, c3}), .LDPIPEEN(c3), .REGRST(c0));
  wire d19;
  IDELAYE2 #(.IDELAY_TYPE("VAR_LOAD"),.PIPE_SEL("TRUE")) u19(.IDATAIN(p19), .DATAOUT(d19), .C(gclk), .CE(c0), .INC(c1), .LD(c2), .CNTVALUEIN({c3, c2, c1, c0, c3}));
  wire d20;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE")) u20(.IDATAIN(p20), .DATAOUT(d20), .C(gclk), .CE(1'b1), .INC(c1));
  wire d21;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE")) u21(.IDATAIN(p21), .DATAOUT(d21), .C(gclk), .CE(1'b0), .INC(c1));
  wire d22;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE")) u22(.IDATAIN(p22), .DATAOUT(d22), .C(gclk), .CE(c0), .INC(1'b1));
  wire d23;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE")) u23(.IDATAIN(p23), .DATAOUT(d23), .C(gclk), .CE(c0), .INC(c1), .LD(1'b1));
  wire d24;
  IDELAYE2 #(.IDELAY_TYPE("VAR_LOAD")) u24(.IDATAIN(p24), .DATAOUT(d24), .C(gclk), .CE(c0), .INC(c1), .LD(c2), .CNTVALUEIN(5'd7));
  wire d25;
  wire [4:0] cnt25;
  IDELAYE2 #(.IDELAY_TYPE("VARIABLE")) u25(.IDATAIN(p25), .DATAOUT(d25), .C(gclk), .CE(c0), .INC(c1), .CNTVALUEOUT(cnt25));
  wire d26;
  wire [4:0] cnt26;
  IDELAYE2 u26(.IDATAIN(p26), .DATAOUT(d26), .CNTVALUEOUT(cnt26));
  wire d27;
  IDELAYE2 u27(.IDATAIN(p27), .DATAOUT(d27), .C(gclk), .CE(c0), .INC(c1), .LD(c2));
  wire d28;
  IDELAYE2 #(.IDELAY_VALUE(13),.HIGH_PERFORMANCE_MODE("TRUE"),.SIGNAL_PATTERN("CLOCK")) u28(.IDATAIN(p28), .DATAOUT(d28));
  wire rdy; IDELAYCTRL ctl(.REFCLK(gclk), .RST(c3), .RDY(rdy));
  always @(posedge gclk) r <= d0 ^ d1 ^ d2 ^ d3 ^ d4 ^ d5 ^ d6 ^ d7 ^ d8 ^ d9 ^ d10 ^ d11 ^ d12 ^ d13 ^ d14 ^ d15 ^ d16 ^ d17 ^ d18 ^ d19 ^ d20 ^ d21 ^ d22 ^ d23 ^ d24 ^ (^cnt25) ^ d25 ^ (^cnt26) ^ d26 ^ d27 ^ d28 ^ rdy;
endmodule
